#import "AiToolRegistry.h"
#import "AiToolBootstrapper.h"

@interface AiToolRegistry ()
@property (nonatomic, strong) NSMutableDictionary<NSString *, id<AiTool>> *tools;
@end

@implementation AiToolRegistry

+ (instancetype)sharedRegistry {
    static AiToolRegistry *instance = nil;
    static dispatch_once_t onceToken;
    dispatch_once(&onceToken, ^{
        instance = [[AiToolRegistry alloc] init];
    });
    return instance;
}

- (instancetype)init {
    self = [super init];
    if (self) {
        _tools = [NSMutableDictionary dictionary];
        // 关键修复（AI 不知道自己能用工具）：此前 [AiToolBootstrapper registerBuiltinTools]
        // 从未被任何地方调用，工具列表始终为空，openAIToolSchemas 返回空数组，
        // 模型收不到任何工具定义，表现为 AI 完全不知道能调用工具。这里在单例 init 时自动注册。
        [AiToolBootstrapper registerBuiltinToolsIntoRegistry:self];
        // 注：此前这里会调用 dumpToolRegistrationDiagnostics 做启动诊断，
        // 每次冷启动都同步写 Documents/ai_tools_dump.txt 并 NSLog 一大段，
        // 属于排查期的临时手段。已移除，避免启动时的磁盘 IO 与日志噪音。
    }
    return self;
}

#pragma mark - 诊断落盘

/// 把注册表真实内容写入 Documents/ai_tools_dump.txt，并 NSLog 一份。
/// 同时探测 3e 新增的类是否存在，用于区分编译问题与注册问题。
- (void)dumpToolRegistrationDiagnostics {
    NSMutableString *out = [NSMutableString string];
    [out appendString:@"===== AiToolRegistry 诊断 =====\n"];
    NSDateFormatter *fmt = [[NSDateFormatter alloc] init];
    fmt.locale = [[NSLocale alloc] initWithLocaleIdentifier:@"zh_CN"];
    [fmt setDateFormat:@"yyyy-MM-dd HH:mm:ss"];
    [out appendFormat:@"时间: %@\n", [fmt stringFromDate:[NSDate date]]];

    NSArray<NSString *> *names = [self.tools.allKeys sortedArrayUsingSelector:@selector(compare:)];
    [out appendFormat:@"已注册工具数: %lu\n", (unsigned long)names.count];
    [out appendString:@"工具列表:\n"];
    for (NSString *n in names) {
        [out appendFormat:@"  - %@\n", n];
    }

    [out appendString:@"\n类存在性探测（nil 表示未编入二进制）:\n"];
    NSArray<NSString *> *probeClasses = @[
        @"AiFileTools",
        @"AiFolderAccessTool",
        @"AiGitHubTreeTool",
        @"AiGitHubTool",
        @"AiWebFetchTool",
    ];
    for (NSString *cn in probeClasses) {
        Class cls = NSClassFromString(cn);
        [out appendFormat:@"  %@ : %@\n", cn, cls ? @"存在" : @"nil（未编入）"];
    }

    [out appendString:@"\n关键工具存在性:\n"];
    NSArray<NSString *> *probeTools = @[
        @"list_instances",
        @"fetch_url",
        @"github_push",
        @"list_roots",
        @"github_tree",
        @"github_read_files",
        @"github_search_code",
        @"folder_request_access",
    ];
    for (NSString *tn in probeTools) {
        [out appendFormat:@"  %@ : %@\n", tn, self.tools[tn] ? @"已注册" : @"缺失"];
    }
    [out appendString:@"===== 诊断结束 =====\n"];

    NSLog(@"[AiToolRegistry] %@", out);

    // 落盘到 Documents（文件 App 可直接查看）
    NSString *docs = [NSSearchPathForDirectoriesInDomains(NSDocumentDirectory, NSUserDomainMask, YES) firstObject];
    if (docs.length > 0) {
        NSString *path = [docs stringByAppendingPathComponent:@"ai_tools_dump.txt"];
        NSError *err = nil;
        BOOL ok = [out writeToFile:path atomically:YES encoding:NSUTF8StringEncoding error:&err];
        if (!ok) {
            NSLog(@"[AiToolRegistry] 诊断文件写入失败: %@", err);
        }
    }
}

- (void)registerTool:(id<AiTool>)tool {
    if (!tool || tool.name.length == 0) return;
    self.tools[tool.name] = tool;
}

- (id<AiTool> _Nullable)toolForName:(NSString *)name {
    if (name.length == 0) return nil;
    return self.tools[name];
}

/// 各工具的显式参数 schema。
/// 背景：早期实现给所有工具都发 `properties: {}`（空对象）。部分 OpenAI 兼容
/// 服务端（尤其国内中转）会严格校验函数定义，判定「空 properties + 空 required」
/// 为非法 schema，直接返回 HTTP 400 —— 且与对话长度无关，任何请求必挂。
/// 这里为每个内置工具声明真实参数，既避开校验，也让模型能正确传参。
- (NSDictionary *)schemaForToolName:(NSString *)name {
    // 通用参数（几乎所有文件类工具共用）
    NSDictionary *pathProp = @{@"type": @"string", @"description": @"目标路径（容器内相对路径或已授权目录下的绝对路径）"};
    NSDictionary *contentProp = @{@"type": @"string", @"description": @"要写入/追加的文本内容"};

    NSDictionary *map = @{
        // ---- 实例 / 版本 ----
        @"list_instances": @{},
        @"list_game_versions": @{@"minecraftVersion": @{@"type": @"string", @"description": @"筛选指定 Minecraft 版本，可省略"}},
        // ---- 日志 / 崩溃 ----
        @"read_latest_log": @{@"instanceName": @{@"type": @"string", @"description": @"实例名，省略则读最新实例"}},
        @"read_crash_report": @{@"instanceName": @{@"type": @"string", @"description": @"实例名，省略则读最新"}},
        @"match_known_errors": @{@"text": @{@"type": @"string", @"description": @"要匹配的报错文本（日志片段）"}},
        // ---- 文件操作 ----
        @"list_files": @{@"path": pathProp},
        @"read_file": @{@"path": pathProp},
        @"grep_files": @{@"pattern": @{@"type": @"string", @"description": @"搜索关键词或正则"},
                          @"path": pathProp},
        @"write_file": @{@"path": pathProp, @"content": contentProp},
        @"edit_file": @{@"path": pathProp,
                         @"oldString": @{@"type": @"string", @"description": @"要被替换的原文本（须唯一匹配）"},
                         @"newString": @{@"type": @"string", @"description": @"替换后的新文本"}},
        @"delete_file": @{@"path": pathProp},
        // ---- 问答 ----
        @"ask": @{@"question": @{@"type": @"string", @"description": @"要问用户的问题"},
                   @"options": @{@"type": @"array", @"description": @"可选项列表",
                                  @"items": @{@"type": @"string"}}},
        // ---- 资源搜索 / 安装 ----
        @"search_mods": @{@"query": @{@"type": @"string", @"description": @"搜索关键词"}},
        @"search_resourcepacks": @{@"query": @{@"type": @"string", @"description": @"搜索关键词"}},
        @"search_shaders": @{@"query": @{@"type": @"string", @"description": @"搜索关键词"}},
        @"search_datapacks": @{@"query": @{@"type": @"string", @"description": @"搜索关键词"}},
        @"search_modpacks": @{@"query": @{@"type": @"string", @"description": @"搜索关键词"}},
        @"search_worlds": @{@"query": @{@"type": @"string", @"description": @"搜索关键词"}},
        @"install_mod": @{@"projectId": @{@"type": @"string", @"description": @"项目 ID"},
                           @"instanceName": @{@"type": @"string", @"description": @"目标实例名"}},
        @"install_resourcepack": @{@"projectId": @{@"type": @"string"}, @"instanceName": @{@"type": @"string"}},
        @"install_shader": @{@"projectId": @{@"type": @"string"}, @"instanceName": @{@"type": @"string"}},
        @"install_datapack": @{@"projectId": @{@"type": @"string"}, @"instanceName": @{@"type": @"string"}},
        @"install_game_version": @{@"version": @{@"type": @"string", @"description": @"要安装的游戏版本号"}},
        @"install_loader": @{@"version": @{@"type": @"string"},
                              @"loaderType": @{@"type": @"string", @"description": @"fabric/forge/neoforge/quilt/optifine"},
                              @"loaderVersion": @{@"type": @"string", @"description": @"加载器版本，可省略"}},
        // ---- 设置 / 待办 / 等待 ----
        @"get_settings": @{},
        @"set_setting": @{@"key": @{@"type": @"string", @"description": @"设置项键名"},
                           @"value": @{@"type": @"string", @"description": @"设置项值"}},
        @"todo_write": @{@"todos": @{@"type": @"array", @"description": @"待办列表",
                                      @"items": @{@"type": @"object",
                                                  @"properties": @{@"content": @{@"type": @"string"},
                                                                    @"status": @{@"type": @"string"}}}}},
        @"sleep": @{@"seconds": @{@"type": @"number", @"description": @"等待秒数"}},
        // ---- 网络 / GitHub ----
        @"fetch_url": @{@"url": @{@"type": @"string", @"description": @"要抓取的完整 URL"}},
        @"github_tree": @{@"repo": @{@"type": @"string", @"description": @"仓库全名 owner/repo"},
                           @"branch": @{@"type": @"string", @"description": @"分支名，省略用默认分支"}},
        @"github_read_files": @{@"repo": @{@"type": @"string"},
                                 @"paths": @{@"type": @"array", @"description": @"要读取的文件路径列表",
                                              @"items": @{@"type": @"string"}}},
        @"github_search_code": @{@"repo": @{@"type": @"string"},
                                  @"query": @{@"type": @"string", @"description": @"搜索关键词"}},
        @"github_push": @{@"repo": @{@"type": @"string", @"description": @"仓库全名 owner/repo"},
                           @"branch": @{@"type": @"string", @"description": @"目标分支"},
                           @"message": @{@"type": @"string", @"description": @"提交信息"},
                           @"files": @{@"type": @"array", @"description": @"要提交的文件列表",
                                        @"items": @{@"type": @"object",
                                                    @"properties": @{@"path": @{@"type": @"string"},
                                                                      @"content": @{@"type": @"string"}}}}},
        // ---- 目录授权 ----
        @"folder_request_access": @{@"reason": @{@"type": @"string", @"description": @"申请授权的理由"}},
        @"folder_list_authorized": @{},
        @"folder_revoke_access": @{@"path": pathProp},
    };

    NSDictionary *props = map[name];
    if (!props) {
        // 未知工具：给一个合法的宽松 schema（additionalProperties 允许任意字段），
        // 绝不发空 properties —— 空 properties 会被严格服务端判非法。
        return @{
            @"type": @"object",
            @"properties": @{
                @"arguments": @{@"type": @"string", @"description": @"工具参数（JSON 字符串形式）"},
            },
            @"additionalProperties": @YES,
        };
    }
    if (props.count == 0) {
        // 无参工具：仍然给一个可选的占位字段，避免空 properties。
        return @{
            @"type": @"object",
            @"properties": @{
                @"_unused": @{@"type": @"string", @"description": @"无参数工具，可忽略此字段"},
            },
            @"additionalProperties": @YES,
        };
    }
    return @{
        @"type": @"object",
        @"properties": props,
        @"additionalProperties": @YES,
    };
}

/// OpenAI 风格 schema：description 用 summary；parameters 由 schemaForToolName 提供。
- (NSArray<NSDictionary *> *)openAIToolSchemas {
    NSMutableArray<NSDictionary *> *schemas = [NSMutableArray array];
    NSArray<NSString *> *sortedNames = [self.tools.allKeys sortedArrayUsingSelector:@selector(compare:)];
    for (NSString *name in sortedNames) {
        id<AiTool> tool = self.tools[name];
        NSDictionary *params = [self schemaForToolName:name] ?: @{};
        // 兜底：任何情况下都不发送空 properties
        if ([params[@"properties"] isKindOfClass:[NSDictionary class]] &&
            [(NSDictionary *)params[@"properties"] count] == 0) {
            params = @{
                @"type": @"object",
                @"properties": @{@"_unused": @{@"type": @"string", @"description": @"无参数工具，可忽略此字段"}},
                @"additionalProperties": @YES,
            };
        }
        [schemas addObject:@{
            @"type": @"function",
            @"function": @{
                @"name": tool.name,
                @"description": tool.summary ?: @"",
                @"parameters": params,
            },
        }];
    }
    return schemas;
}

#pragma mark - 参数规范化

/// 把一个键规范化成小写 camelCase（例如 "game-version"→"gameVersion"、"InstanceName"→"instanceName"）。
- (NSString *)normalizedKeyCamel:(NSString *)key {
    if (key.length == 0) return key;

    NSUInteger length = key.length;
    // 记录每个"词"的起始下标（词与词之间由分隔符或大小写驼峰边界隔开）
    NSMutableIndexSet *wordStarts = [NSMutableIndexSet indexSet];
    [wordStarts addIndex:0];
    for (NSUInteger i = 1; i < length; i++) {
        unichar c = [key characterAtIndex:i];
        if (c == '_' || c == '-' || c == '.' || c == ' ' || c == '/') {
            continue; // 分隔符本身不成为词头
        }
        unichar prev = [key characterAtIndex:i - 1];
        BOOL prevIsSep = (prev == '_' || prev == '-' || prev == '.' || prev == ' ' || prev == '/');
        BOOL prevIsLower = (prev >= 'a' && prev <= 'z') || (prev >= '0' && prev <= '9');
        BOOL isUpper = (c >= 'A' && c <= 'Z');
        if (prevIsSep) {
            [wordStarts addIndex:i];
        } else if (isUpper && prevIsLower) {
            // 驼峰边界：小写/数字后紧跟大写（兼顾 PascalCase 与 camelCase）
            [wordStarts addIndex:i];
        }
    }

    NSMutableString *result = [NSMutableString string];
    NSMutableString *currentWord = [NSMutableString string];
    __block BOOL isFirstWord = YES;

    void (^flush)(void) = ^{
        if (currentWord.length == 0) return;
        if (isFirstWord) {
            // 首词整体保持小写
            [result appendString:currentWord];
            isFirstWord = NO;
        } else {
            // 后续词首字母大写、其余小写
            NSString *word = currentWord;
            NSString *capitalized = [word stringByReplacingCharactersInRange:NSMakeRange(0, 1)
                                                                  withString:[[word substringToIndex:1] uppercaseString]];
            [result appendString:capitalized];
        }
        [currentWord setString:@""];
    };

    for (NSUInteger i = 0; i < length; i++) {
        unichar c = [key characterAtIndex:i];
        if (c == '_' || c == '-' || c == '.' || c == ' ' || c == '/') {
            flush();
            continue;
        }
        if (i > 0 && [wordStarts containsIndex:i]) {
            flush();
        }
        // 统一转小写
        unichar lower = (c >= 'A' && c <= 'Z') ? (unichar)(c - 'A' + 'a') : c;
        [currentWord appendString:[NSString stringWithFormat:@"%C", lower]];
    }
    flush();
    return result;
}

/// 判断 value 是否"为空"（丢弃的键包括 nil、NSNull、空字符串）
- (BOOL)isEmptyValue:(id)value {
    if (value == nil || [value isKindOfClass:[NSNull class]]) return YES;
    if ([value isKindOfClass:[NSString class]]) {
        return [(NSString *)value length] == 0;
    }
    return NO;
}

- (NSDictionary * _Nonnull)normalizedParams:(NSDictionary * _Nonnull)params {
    if (![params isKindOfClass:[NSDictionary class]]) return @{};
    NSMutableDictionary *normalized = [NSMutableDictionary dictionary];
    [params enumerateKeysAndObjectsUsingBlock:^(id rawKey, id value, BOOL *stop) {
        NSString *key = [rawKey isKindOfClass:[NSString class]] ? (NSString *)rawKey : [rawKey description];
        NSString *camelKey = [self normalizedKeyCamel:key];
        if (camelKey.length == 0) return;
        if ([self isEmptyValue:value]) return; // 丢弃 value 为空 的键
        normalized[camelKey] = value;
    }];
    return normalized;
}

#pragma mark - 执行

- (void)executeToolNamed:(NSString *)name
                  params:(NSDictionary *)params
              completion:(void (^)(NSString * _Nullable result, NSError * _Nullable error))completion {
    id<AiTool> tool = [self toolForName:name];
    if (!tool) {
        if (completion) {
            dispatch_async(dispatch_get_main_queue(), ^{
                NSError *err = [NSError errorWithDomain:@"AiTool" code:404
                                               userInfo:@{NSLocalizedDescriptionKey: [NSString stringWithFormat:@"未知工具 %@", name ?: @""]}];
                completion(nil, err);
            });
        }
        return;
    }

    // 先规范化参数再透传给工具 execute
    NSDictionary *normalized = [self normalizedParams:params];
    [tool execute:normalized completion:^(NSString * _Nullable result, NSError * _Nullable error) {
        // 统一把结果回调到主线程
        dispatch_async(dispatch_get_main_queue(), ^{
            if (completion) {
                completion(result, error);
            }
        });
    }];
}

@end
